// Fumadocs takes a code block's icon as raw markup, so each one arrives already
// wrapped and keeps its own colours instead of inheriting the text colour.
export const codeBlockIcons: Record<string, string> = Object.fromEntries(
  Object.entries(languageIcons).map(([key, icon]) => [
    key,
    `<svg viewBox="${icon.viewBox}">${icon.markup}</svg>`,
  ]),
);